    // 1. Validate output pointers
    if ((momentum == NULL) || (momentum_norm == NULL) || 
        (energy_axis == NULL) || (energy == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Zero all outputs as required before any processing or failure handling
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *momentum_norm = 0.0;
    *energy_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    *energy = 0.0;

    // 3. Validate input wheels pointer
    if (wheels == NULL) {
        return ADCS_E_NULL;
    }

    // 4. Validate count range
    if (count < 1 || count > 16) {
        return ADCS_E_RANGE;
    }

    // 5. Iterate through each wheel to validate and accumulate energy terms
    adcs_vec3_t norm_axis;
    double kinetic_energy;
    size_t i;

    for (i = 0; i < count; ++i) {
        // Check inertia: must be finite and positive
        if (!isfinite(wheels[i].inertia_kg_m2) || wheels[i].inertia_kg_m2 <= 0.0) {
            return ADCS_E_RANGE;
        }

        // Check speed: must be finite
        if (!isfinite(wheels[i].speed_rad_s)) {
            return ADCS_E_RANGE;
        }

        // Check axis: must be finite
        if (!adcs_is_finite_vec3(&wheels[i].axis_body)) {
            return ADCS_E_RANGE;
        }

        // Calculate axis norm
        double axis_norm = adcs_vec3_norm(&wheels[i].axis_body);

        // Check axis norm threshold
        if (axis_norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }

        // Normalize axis manually for energy_axis accumulation
        norm_axis.x = wheels[i].axis_body.x / axis_norm;
        norm_axis.y = wheels[i].axis_body.y / axis_norm;
        norm_axis.z = wheels[i].axis_body.z / axis_norm;

        // Calculate kinetic energy: e_i = 0.5 * inertia * speed^2
        kinetic_energy = 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;

        // Accumulate total energy
        *energy += kinetic_energy;

        // Accumulate energy_axis: sum(e_i * normalize(axis))
        energy_axis->x += kinetic_energy * norm_axis.x;
        energy_axis->y += kinetic_energy * norm_axis.y;
        energy_axis->z += kinetic_energy * norm_axis.z;
    }

    // 6. Compute linked-library cluster momentum
    adcs_status_t res = adcs_wheel_momentum(wheels, count, momentum);
    if (res != ADCS_OK) {
        // If library function fails, outputs remain zeroed as per requirement
        return res;
    }

    // 7. Compute momentum norm
    *momentum_norm = adcs_vec3_norm(momentum);

    return ADCS_OK;
}

