        if (!isfinite(inertia) || !isfinite(speed) || inertia <= 0.0) {
            return ADCS_E_RANGE;
        }

        double axis_norm = adcs_vec3_norm(&axis);
        if (!isfinite(axis_norm) || axis_norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }

        double e_i = 0.5 * inertia * speed * speed;
        total_energy += e_i;

        adcs_vec3_t normalized_axis = adcs_vec3_scale(&axis, 1.0 / axis_norm);
        adcs_vec3_t term = adcs_vec3_scale(&normalized_axis, e_i);
        energy_axis_acc = adcs_vec3_add(&energy_axis_acc, &term);
    }

    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    // Since we already validated inputs, status should be ADCS_OK. 
