    // We already zeroed at the start. If it fails here, we just proceed with what we have?
    // No, "Failure zeros all outputs". We already zeroed.

    *momentum_norm = adcs_vec3_norm(momentum);
    *energy_axis = energy_axis_acc;
    *energy = total_energy;

    return ADCS_OK;
}

